import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import { createMSDFMesh } from '@/text';
export default function createNode(config, ctx) {
  const root = new THREE.Group();
  const pos = config.position || [0, 0, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  root.position.set(pos[0], pos[1], pos[2]);
  root.rotation.set(rot[0], rot[1], rot[2]);
  root.scale.set(scl[0], scl[1], scl[2]);
  // Load main GLB
  const glb = ctx.glbLoader(config.assets?.meshUrl);
  const model = glb.scene ?? glb;
  root.add(model);
  // Text creation
  const colors = config.visual?.colors ?? {};
  const inkColor = new THREE.Color(colors.ink ?? '#16161d');
  const accentColor = new THREE.Color(colors.accent ?? '#ff2a38');
  const textDefs = config.textContent ?? {};
  const headline = createMSDFMesh(
    textDefs.headline ?? '',
    {
      fontSize: 68,
      fontWeight: 600,
      family: 'Lora',
      color: inkColor,
      letterSpacing: -0.005,
      lineHeight: 1.1,
    },
    ctx.fontAtlas
  );
  headline.position.set(0, -1.5, 0);
  root.add(headline);
  const body = createMSDFMesh(
    textDefs.body ?? '',
    {
      fontSize: 26,
      fontWeight: 400,
      family: 'JetBrains Mono',
      color: inkColor,
      letterSpacing: 0,
      lineHeight: 1.5,
    },
    ctx.fontAtlas
  );
  body.position.set(0, -1.75, 0);
  root.add(body);
  const caption = createMSDFMesh(
    textDefs.caption ?? '',
    {
      fontSize: 18,
      fontWeight: 400,
      family: 'JetBrains Mono',
      color: accentColor,
      letterSpacing: 0.08,
      lineHeight: 1.4,
    },
    ctx.fontAtlas
  );
  caption.position.set(0, -2.25, 0);
  root.add(caption);
  // Apply cinematic primitives
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      fn(root, prim.params ?? {});
    }
  }
  // Orbit handling (continuous rotation)
  const orbitPrim = primitives.find(p => p.name === 'orbit');
  let orbitCallback = null;
  if (orbitPrim && orbitPrim.params?.speed) {
    const speed = orbitPrim.params.speed;
    orbitCallback = (delta) => {
      root.rotation.y += speed * delta;
    };
    gsap.ticker.add(orbitCallback);
  }
  // Depth‑rotate hover handlers
  const depthPrim = primitives.find(p => p.name === 'depth-rotate');
  const handlers = {};
  if (depthPrim && depthPrim.params?.maxDeg) {
    const maxRad = THREE.MathUtils.degToRad(depthPrim.params.maxDeg);
    const hoverEnter = () => {
      gsap.to(root.rotation, {
        x: maxRad,
        duration: 0.3,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
      });
      gsap.to(root.scale, {
        x: 1.04,
        y: 1.04,
        z: 1.04,
        duration: 0.3,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
      });
    };
    const hoverLeave = () => {
      gsap.to(root.rotation, {
        x: 0,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      });
      gsap.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      });
    };
    handlers.pointerenter = hoverEnter;
    handlers.pointerleave = hoverLeave;
  }
  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (orbitCallback) {
      gsap.ticker.remove(orbitCallback);
    }
    gsap.killTweensOf(root);
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) {
          obj.geometry.dispose();
        }
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose && m.dispose());
          } else {
            obj.material.dispose && obj.material.dispose();
          }
        }
      }
    });
  };
  return root;
}
